import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Asset that carries the licence notices of everything compiled into the
/// bundled spatial viewer (Spark, three.js, fflate, Spark's WebAssembly crates).
/// Generated by `assets/spatial_viewer/build.mjs` from `third_party/licenses/`.
const String spatialViewerLicensesAsset =
    'assets/spatial_viewer/THIRD_PARTY_LICENSES.txt';

/// Packages named on the in-app licence page for that asset.
const List<String> spatialViewerLicensePackages = <String>[
  '@sparkjsdev/spark',
  'three',
  'fflate (inlined by Spark)',
  'Rust crates in Spark\'s WebAssembly module',
];

bool _registered = false;

/// Makes the spatial viewer's third-party notices appear on the standard
/// `showLicensePage` screen, so the MIT and Zlib notices travel with every
/// build (store builds and web alike) and not only with the repository.
///
/// Safe to call more than once; only the first call registers. The text is read
/// lazily, when the licence page is opened.
void registerSpatialViewerLicenses({AssetBundle? bundle}) {
  if (_registered) return;
  _registered = true;
  LicenseRegistry.addLicense(() async* {
    final text = await (bundle ?? rootBundle).loadString(
      spatialViewerLicensesAsset,
    );
    yield LicenseEntryWithLineBreaks(spatialViewerLicensePackages, text);
  });
}

@visibleForTesting
void resetSpatialViewerLicenseRegistrationForTest() => _registered = false;
